    // Guided product tour
    tourWelcomeTitle: 'Welcome to Ope!',
    tourWelcomeBody: "Ope helps you know how busy your business will be — so you can order the right stock, schedule the right staff, and never be caught off guard. Let's take a quick look at what's here.",
    tourQuickActionsTitle: 'Your quick actions',
    tourQuickActionsBody: "These three buttons are your everyday tools. \"Record a Sale\" counts each sale in real time. \"Log Today\" enters today's totals after you close. \"Record a Regular\" notes a loyal customer's visit.",
    tourForecastTitle: 'Your demand forecast',
    tourForecastBody: "Once you've logged a few days, this chart shows how busy each day of the coming week is likely to be — so you can plan ahead. It gets more accurate the more you log.",
    tourBusyHoursTitle: 'Busy hours',
    tourBusyHoursBody: "Here you'll see which hours tomorrow are expected to be busiest and how many staff you might need at peak time. It uses the tap-by-tap data you record with \"Record a Sale\".",
    tourPredictionsTitle: 'Predictions',
    tourPredictionsBody: "The Predictions tab shows your weekly forecast in detail, plus what to order for each product and when. Ope learns your patterns and updates these automatically as you log more days.",
    tourInsightsTitle: "Insights — what Ope has learned",
    tourInsightsBody: "This screen shows what Ope has figured out about your business from your real data: your busiest day, peak hours, year-over-year growth, and early warnings about things that are changing.",
    tourHistoryTitle: 'History',
    tourHistoryBody: "Under History, you can view all your past logged days, add a day you forgot, see monthly trends, or import a whole spreadsheet of past data at once.",
    tourManageTitle: 'Manage',
    tourManageBody: "Under Manage you'll find your products, loyal regulars, recurring patterns, promos, and settings. This is where you teach Ope about your business — the more you add, the smarter it gets.",
    tourDoneTitle: "You're all set!",
    tourDoneBody: "Ope gets smarter the more you log. Start by recording today's sales — then check back in a couple of weeks to see your first forecast. You can replay this tour any time from Settings.",
    tourBack: '← Back',
    tourNext: 'Next →',
    tourFinish: "Let's go!",
