    tourPredictionsTitle: 'पूर्वानुमान',
    tourPredictionsBody: '"पूर्वानुमान" टैब विस्तृत साप्ताहिक पूर्वानुमान दिखाता है, साथ ही हर उत्पाद के लिए क्या और कब ऑर्डर करना है। Ope आपके पैटर्न सीखता है और जैसे-जैसे आप अधिक दिन लॉग करते हैं, इन्हें स्वचालित रूप से अपडेट करता है।',
